{"files":[{"path":"index.html","old_sha256":"76cda301f0d1bf073c55adb7fc2ed12e84814a4c889266cd8a8bfce658ba446c","content":"<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Voxel Sandbox</title>
<link rel="stylesheet" href="style.css">
</head>
<body>
<header>
  <h1>Voxel Sandbox</h1>
  <div class="hud">
    <div id="world">world 8x8</div>
    <div id="position">1,1,1</div>
    <div id="facing">east</div>
    <div id="selected">none</div>
    <div id="status">ready</div>
  </div>
  <div class="controls">
    <button id="turn-left">Turn Left</button>
    <button id="turn-right">Turn Right</button>
    <button id="break">Break</button>
    <select id="hotbar"><option value="dirt" selected>dirt</option><option value="stone">stone</option></select>
    <button id="place">Place</button>
    <button id="save">Save</button>
    <button id="load">Load</button>
  </div>
</header>
<main>
  <div id="scene"></div>
</main>
<script src="world.js"></script>
<script src="rules.js"></script>
<script src="storage.js"></script>
<script src="app.js"></script>
</body>
</html>
"},{"path":"storage.js","old_sha256":null,"content":"const Storage = {
  key: 'voxel-save',
  facingOrder: ['east', 'south', 'west', 'north'],
  save(World) {
    const blocks = [];
    for (const k in World.blocks) {
      const b = World.blocks[k];
      if (b.material === 'dirt' || b.material === 'stone') blocks.push([b.x, b.y, b.z, b.material]);
    }
    const facing = this.facingOrder.indexOf(World.player.facing);
    const data = { version: 1, blocks, player: [World.player.x, 1, World.player.z], facing };
    try { localStorage.setItem(this.key, JSON.stringify(data)); return true; }
    catch (e) { return false; }
  },
  load(World) {
    let raw;
    try { raw = localStorage.getItem(this.key); } catch (e) { return null; }
    if (!raw) return null;
    let d;
    try { d = JSON.parse(raw); } catch (e) { return null; }
    if (!d || d.version !== 1) return null;
    if (!Array.isArray(d.blocks) || !Array.isArray(d.player) || d.player.length !== 3) return null;
    if (typeof d.facing !== 'number' || d.facing < 0 || d.facing > 3 || d.facing % 1 !== 0) return null;
    const seen = {};
    for (const b of d.blocks) {
      if (!Array.isArray(b) || b.length !== 4) return null;
      const [x, y, z, m] = b;
      if (![x, y, z].every(n => Number.isInteger(n))) return null;
      if (!World.inBounds(x, y, z)) return null;
      if (m !== 'dirt' && m !== 'stone') return null;
      const k = x + ',' + y + ',' + z;
      if (seen[k]) return null;
      seen[k] = true;
    }
    const [px, py, pz] = d.player;
    if (![px, py, pz].every(n => Number.isInteger(n))) return null;
    if (py !== 1) return null;
    if (!World.inBounds(px, py, pz)) return null;
    if (seen[px + ',' + py + ',' + pz]) return null;
    if (seen[px + ',' + (py + 1) + ',' + pz]) return null;
    return { blocks: d.blocks, player: [px, 1, pz], facing: this.facingOrder[d.facing] };
  }
};
